package cli

import (
	"fmt"
	"io"
	"strings"

	"github.com/Thuya-Myint/socklens/internal/terminal"
)

// Socket cells contain ASCII: endpoints/PIDs/states are generated by the
// backends and process names are quoted to ASCII before reaching the renderer.
// Wrap before styling so ANSI bytes never consume screen columns. Values are
// continued in full, never truncated or replaced with ellipses.
func writeFolded(out io.Writer, role terminal.Role, text string, columns int) error {
	for columns > 0 && len(text) > columns {
		cut, next := columns, columns
		if space := strings.LastIndexByte(text[:columns+1], ' '); space > 0 {
			cut, next = space, space+1
		}
		if _, err := fmt.Fprintln(out, terminal.Style(out, role, text[:cut])); err != nil {
			return err
		}
		text = text[next:]
	}
	_, err := fmt.Fprintln(out, terminal.Style(out, role, text))
	return err
}

func writeSocketField(out io.Writer, label, value string, columns int) error {
	prefix := "  " + label + ": "
	if columns < 16 {
		if err := writeFolded(out, terminal.Muted, label+":", columns); err != nil {
			return err
		}
		prefix = strings.Repeat(" ", min(2, columns-1))
	}
	remaining := columns - len(prefix)
	indent := strings.Repeat(" ", len(prefix))
	for len(value) > remaining {
		if _, err := fmt.Fprintln(out, terminal.Style(out, terminal.Muted, prefix)+value[:remaining]); err != nil {
			return err
		}
		value = value[remaining:]
		prefix = indent
	}
	_, err := fmt.Fprintln(out, terminal.Style(out, terminal.Muted, prefix)+value)
	return err
}

func writeStackedSockets(out io.Writer, cells [][6]string, columns int) error {
	for _, line := range cells {
		if err := writeFolded(out, stateRole(line[3]), line[0]+"  "+line[3], columns); err != nil {
			return err
		}
		for _, field := range []struct{ label, value string }{
			{"Local", line[1]}, {"Remote", line[2]}, {"PIDs", line[4]}, {"Processes", line[5]},
		} {
			if err := writeSocketField(out, field.label, field.value, columns); err != nil {
				return err
			}
		}
		if _, err := fmt.Fprintln(out); err != nil {
			return err
		}
	}
	return nil
}

// Observation headings also reflow so narrow watch output keeps a readable
// timestamp and counts rather than relying on the terminal's implicit wrapping.
func writeObservationHeading(out io.Writer, label, details string) error {
	if _, err := fmt.Fprintln(out); err != nil {
		return err
	}
	columns := terminal.Width(out)
	if columns > 0 && len(label)+1+len(details) > columns {
		if err := writeFolded(out, terminal.Heading, label, columns); err != nil {
			return err
		}
		return writeFolded(out, terminal.Muted, details, columns)
	}
	_, err := fmt.Fprintf(out, "%s %s\n", terminal.Style(out, terminal.Heading, label), details)
	return err
}
